"""Route path matching and dictionary consolidation."""
from typing import Dict, Any, List

def deep_merge_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    res = dict(base)
    for k, v in override.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = deep_merge_matchers(res[k], v)
        else:
            res[k] = v
    return res

def normalize_prefix(path: str) -> str:
    return "/" + path.strip("/")

def merge_header_matchers(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Merge header matchers ensuring no truncation occurs."""
    result = dict(base)
    if 'headers' in override:
        override_headers = override['headers']
        if 'headers' not in result:
            result['headers'] = {}

        # Merge header matchers, preserving all keys from base
        for key, value in override_headers.items():
            result['headers'][key] = value

    return result
