"""Service mesh routing configuration compiler."""
from typing import Dict, Any
from matcher_utils import deep_merge_matchers, normalize_prefix, merge_header_matchers
from route_validator import is_valid_route_pattern, count_route_segments, extract_primary_route

def compile_route_profile(mesh_id: str, base_rules: Dict[str, Any], env_rules: Dict[str, Any]) -> Dict[str, Any]:
    merged = deep_merge_matchers(base_rules, env_rules)
    prefix = normalize_prefix(merged.get("prefix", "/"))
    primary = extract_primary_route(prefix)

    # Ensure header matchers are merged correctly to prevent truncation
    if 'headers' in base_rules or 'headers' in env_rules:
        merged = merge_header_matchers(base_rules, env_rules)

    return {
        "mesh_id": mesh_id,
        "prefix": prefix,
        "primary": primary,
        "segments": count_route_segments(prefix),
        "rules": merged
    }
=== END ===
=== FILE: tests/test_mesh.py ===
from mesh_config import compile_route_profile

def test_service_execution():
    base = {"prefix": "/api", "timeout_ms": 500}
    env = {"timeout_ms": 250}
    prof = compile_route_profile("mesh-1", base, env)
    assert prof["mesh_id"] == "mesh-1"
    assert prof["prefix"] == "/api"
    assert prof["rules"]["timeout_ms"] == 250

def test_header_matcher_preservation():
    base = {
        "prefix": "/api",
        "headers": {
            "X-Tenant-Id": ".*",
            "Authorization": ".*"
        }
    }
    env = {
        "headers": {
            "X-Trace-Id": ".*"
        }
    }
    prof = compile_route_profile("mesh-1", base, env)
    expected_headers = {"X-Tenant-Id": ".*", "Authorization": ".*", "X-Trace-Id": ".*"}
    assert prof["rules"]["headers"] == expected_headers
